interface.definition:
a!localVariables(
  local!selectedLayout: if(
    #"SYSTEM_SYSRULES_isPageWidth"({ "PHONE", "TABLET_PORTRAIT" }),
    "LIST",
    "SPLIT"
  ),
  local!documentAggregate: #"SYSTEM_SYSRULES_queryRecordType_v4"(
    recordType: #"urn:appian:record-type:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d",
    fields: {
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/4a1710f5-b585-4798-bbb5-97b5e8432920",
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/b4519f8d-9dfd-45ce-8f58-d3e41e61bf2f",
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/4620d3f5-124d-4df6-972e-5f7f6726a771",
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/27288931-87a4-47bf-b03f-3308347200af",
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/3a918686-bbbe-4075-b7f5-4ebb9ffbd630",
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/1d521b70-29b8-4931-b760-12135b612bdc",
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/f5eb566a-79ce-4203-a742-6a4fe4bc5535",
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/12c57e44-9e24-4514-9fac-24934e6fe7db",
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/23358f06-5296-4eaa-860f-8f25f7071ba7",
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_name",
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_dateCreated",
      #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_extension"
    },
    filters: #"SYSTEM_SYSRULES_queryLogicalExpression"(
      operator: "AND",
      filters: {
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/23358f06-5296-4eaa-860f-8f25f7071ba7",
          operator: "not null"
        ),
        #"SYSTEM_SYSRULES_queryFilter"(
          field: #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/b4519f8d-9dfd-45ce-8f58-d3e41e61bf2f",
          operator: "=",
          value: ri!PQRDSF[#"urn:appian:record-field:v1:8460a530-e87d-441b-b904-41fbd8172f32/53285f69-f746-487b-9faa-433d051f6ba3"]
        )
      },
      ignoreFiltersWithEmptyValues: true
    ),
    pagingInfo: #"SYSTEM_SYSRULES_pagingInfo"(startIndex: 1, batchSize: 100)
  ).data,
  local!selectedDocument: 1,
  local!isExpandedView: local!selectedLayout = "LIST",
  local!selectable: local!selectedLayout <> "LIST",
  #"SYSTEM_SYSRULES_headerContentLayout"(
    header: {
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: #"SYSTEM_SYSRULES_sideBySideLayout"(
          items: {
            #"SYSTEM_SYSRULES_sideBySideItem"(),
            #"SYSTEM_SYSRULES_sideBySideItem"(
              item: #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                buttons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
                  tooltip: "Vista dividida",
                  saveInto: a!save(local!selectedLayout, "SPLIT"),
                  icon: "columns",
                  style: if(
                    local!selectedLayout = "SPLIT",
                    "SOLID",
                    "OUTLINE"
                  )
                ),
                marginBelow: "NONE",
                align: "END"
              ),
              width: "MINIMIZE"
            ),
            #"SYSTEM_SYSRULES_sideBySideItem"(
              item: #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                buttons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
                  tooltip: "Vista de lista",
                  saveInto: a!save(local!selectedLayout, "LIST"),
                  icon: "list-ul",
                  style: if(
                    local!selectedLayout = "LIST",
                    "SOLID",
                    "OUTLINE"
                  )
                ),
                marginBelow: "NONE",
                align: "END"
              ),
              width: "MINIMIZE"
            )
          },
          alignVertical: "MIDDLE",
          spacing: "DENSE"
        ),
        showBorder: false
      )
    },
    contents: {
      #"SYSTEM_SYSRULES_paneLayout"(
        panes: {
          #"SYSTEM_SYSRULES_pane"(
            contents: {
              #"SYSTEM_SYSRULES_cardLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_richTextDisplayField"(
                    value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: "Documentos " & "(" & count(local!documentAggregate) & ")",
                      size: "MEDIUM",
                      style: "STRONG"
                    ),
                    showWhen: count(local!documentAggregate) <> 0
                  ),
                  #"SYSTEM_SYSRULES_gridField_v4"(
                    data: local!documentAggregate,
                    columns: {
                      #"SYSTEM_SYSRULES_gridColumn"(
                        value: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: {
                            #"_a-0001eee3-3e88-8000-9cdc-011c48011c48_5389235"(
                              documentExtension: fv!row[#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_extension"],
                              size: "STANDARD"
                            ),
                            char(32),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: fv!row[#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_name"],
                              style: "STRONG",
                              linkStyle: "STANDALONE"
                            ),
                            char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: {
                                /*datetext(fv!row['recordType!{8460a530-e87d-441b-b904-41fbd8172f32}PQR PQRDSF.relationships.{b128415f-8955-42d1-b07a-2a65c22ff4e9}documentProperties.fields.{SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_dateCreated}dateCreated'], "dd/MM/yyyy HH:MM a") & " (" & fv!row['recordType!{2f0fafa3-e100-47a2-8986-5d1e779a676d}SPK PQRDSFEvento.fields.{27288931-87a4-47bf-b03f-3308347200af}usuario'] & ")"*/
                                datetext(now(), "dd/MM/yyyy HH:MM a") & " (" & now() & ")"
                              },
                              size: "SMALL"
                            )
                          }
                        ),
                        sortField: #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_name",
                        showWhen: not(local!isExpandedView)
                      ),
                      #"SYSTEM_SYSRULES_gridColumn"(
                        label: "Nombre",
                        value: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: {
                            #"_a-0001eee3-3e88-8000-9cdc-011c48011c48_5389235"(
                              documentExtension: fv!row[#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_extension"],
                              size: "STANDARD"
                            ),
                            char(32),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: fv!row[#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_name"],
                              link: #"SYSTEM_SYSRULES_documentDownloadLink"(
                                document: fv!row[#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/23358f06-5296-4eaa-860f-8f25f7071ba7"]
                              ),
                              linkStyle: "STANDALONE"
                            )
                          }
                        ),
                        sortField: #"urn:appian:record-field:v1:8460a530-e87d-441b-b904-41fbd8172f32/b128415f-8955-42d1-b07a-2a65c22ff4e9/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_name",
                        showWhen: local!isExpandedView
                      ),
                      #"SYSTEM_SYSRULES_gridColumn"(
                        label: "Usuario",
                        value: fv!row[#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/27288931-87a4-47bf-b03f-3308347200af"],
                        sortField: #"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/27288931-87a4-47bf-b03f-3308347200af",
                        showWhen: local!isExpandedView,
                        align: "CENTER",
                        width: "NARROW_PLUS"
                      ),
                      #"SYSTEM_SYSRULES_gridColumn"(
                        label: "Comentario",
                        value: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: fv!row[#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/1d521b70-29b8-4931-b760-12135b612bdc"]
                        ),
                        showWhen: local!isExpandedView
                      ),
                      #"SYSTEM_SYSRULES_gridColumn"(
                        value: #"SYSTEM_SYSRULES_recordActionField_v1"(actions: {}, style: "MENU_ICON"),
                        showWhen: local!isExpandedView,
                        align: "CENTER",
                        width: "ICON"
                      )
                    },
                    pageSize: 10,
                    selectable: local!selectable,
                    selectionStyle: "ROW_HIGHLIGHT",
                    selectionValue: local!selectedDocument,
                    selectionSaveInto: a!save(
                      local!selectedDocument,
                      index(reverse(save!value), 1, null)
                    ),
                    borderStyle: "LIGHT",
                    shadeAlternateRows: false,
                    refreshAfter: "RECORD_ACTION"
                  )
                },
                showWhen: count(local!documentAggregate) <> 0,
                showShadow: true,
                padding: "LESS"
              )
            },
            width: if(
              local!selectedLayout = "LIST",
              "AUTO",
              "MEDIUM"
            ),
            backgroundColor: "TRANSPARENT",
            padding: "LESS"
          ),
          #"SYSTEM_SYSRULES_pane"(
            contents: {
              #"SYSTEM_SYSRULES_boxLayout"(
                label: "Chatea con este documento",
                contents: {
                  #"SYSTEM_SYSRULES_documentsChatField"(
                    label: "Chatbot de documentos",
                    labelPosition: "COLLAPSED",
                    documents: local!documentAggregate[local!selectedDocument][#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/23358f06-5296-4eaa-860f-8f25f7071ba7"],
                    height: "AUTO"
                  )
                },
                showWhen: if(
                  a!isNotNullOrEmpty(local!documentAggregate),
                  contains(
                    {
                      "PDF",
                      "HTML",
                      "DOC",
                      "DOCX",
                      "MD",
                      "CSV",
                      "TXT"
                    },
                    upper(
                      local!documentAggregate[local!selectedDocument][#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_extension"]
                    )
                  ),
                  false
                ),
                isCollapsible: true,
                isInitiallyCollapsed: true,
                marginBelow: "STANDARD",
                style: "STANDARD"
              ),
              #"SYSTEM_SYSRULES_cardLayout"(
                contents: {
                  /*Document name and actions*/
                  #"SYSTEM_SYSRULES_sideBySideLayout"(
                    items: {
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: local!documentAggregate[local!selectedDocument][#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_name"],
                              size: "MEDIUM",
                              style: "STRONG"
                            ),
                            char(10),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: local!documentAggregate[local!selectedDocument][#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/1d521b70-29b8-4931-b760-12135b612bdc"]
                            )
                          },
                          marginAbove: "NONE",
                          marginBelow: "STANDARD"
                        ),
                        width: "AUTO"
                      ),
                      #"SYSTEM_SYSRULES_sideBySideItem"(
                        item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: {
                                #"SYSTEM_SYSRULES_richTextIcon"(icon: "download", caption: "Download")
                              },
                              link: #"SYSTEM_SYSRULES_documentDownloadLink"(
                                local!documentAggregate[local!selectedDocument][#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/23358f06-5296-4eaa-860f-8f25f7071ba7"]
                              )
                            )
                          },
                          marginAbove: "NONE",
                          marginBelow: "NONE",
                          align: "RIGHT"
                        ),
                        width: "MINIMIZE"
                      )
                    },
                    showWhen: a!isNotNullOrEmpty(local!selectedDocument),
                    marginAbove: "NONE",
                    marginBelow: "LESS",
                    alignVertical: "MIDDLE"
                  ),
                  #"SYSTEM_SYSRULES_sectionLayout_v1"(
                    contents: {
                      /*Document summary display goes above this*/
                      a!match(
                        value: lower(
                          local!documentAggregate[local!selectedDocument][#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_extension"]
                        ),
                        /*Document viewer field*/
                        equals: "pdf",
                        equals: "jpg",
                        equals: "png",
                        equals: "txt",
                        then: #"SYSTEM_SYSRULES_documentViewerField"(
                          document: local!documentAggregate[local!selectedDocument][#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/23358f06-5296-4eaa-860f-8f25f7071ba7"],
                          height: "TALL"
                        ),
                        /*Video/audio files*/
                        equals: "mp4",
                        equals: "mov",
                        equals: "mp3",
                        equals: "wav",
                        then: #"SYSTEM_SYSRULES_videoField"(
                          videos: #"SYSTEM_SYSRULES_webVideo"(
                            source: document(
                              local!documentAggregate[local!selectedDocument][#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/23358f06-5296-4eaa-860f-8f25f7071ba7"],
                              "url"
                            )
                          )
                        ),
                        /*equals: "doc",*/
                        /*equals: "docx",*/
                        /*then: microsoftDocumentEditorField(*/
                        /*tokenInfo: generatemicrosoftdocumenteditortoken(*/
                        /*viewMode: "EDIT",*/
                        /*document: local!documentAggregate[local!selectedDocument]['recordType!{205cbf5b-a0bf-43a6-9e7f-02ad4574ac6b}SPK HistoriaUsuarioEvento.fields.{ce49da9c-1a79-470a-876e-900cb22dd3bd}docAnexo']*/
                        /*)*/
                        /*),*/
                        /*All other document types*/
                        default: #"SYSTEM_SYSRULES_cardLayout"(
                          contents: {
                            #"SYSTEM_SYSRULES_sectionLayout_v1"(
                              marginAbove: "EVEN_MORE",
                              marginBelow: "EVEN_MORE"
                            ),
                            if(
                              a!isNullOrEmpty(local!selectedDocument),
                              {},
                              {
                                #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  labelPosition: "COLLAPSED",
                                  value: {
                                    #"_a-0001eee3-3e88-8000-9cdc-011c48011c48_5389235"(
                                      documentExtension: local!documentAggregate[local!selectedDocument][#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_extension"],
                                      size: "EXTRA_LARGE"
                                    ),

                                  },
                                  align: "CENTER"
                                ),
                                #"SYSTEM_SYSRULES_sectionLayout_v1"(marginAbove: "MORE"),
                                #"SYSTEM_SYSRULES_richTextDisplayField"(
                                  label: local!documentAggregate[local!selectedDocument][#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_name"],
                                  labelPosition: "COLLAPSED",
                                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                    text: local!documentAggregate[local!selectedDocument][#"urn:appian:record-field:v1:2f0fafa3-e100-47a2-8986-5d1e779a676d/7aba7c3c-6537-48b1-ae0a-df4939909957/SYSTEM_RECORD_TYPE_DOCUMENT_FIELD_name"],
                                    size: "MEDIUM_PLUS"
                                  ),
                                  align: "CENTER",
                                  marginBelow: "MORE"
                                )
                              }
                            ),
                            #"SYSTEM_SYSRULES_sectionLayout_v1"(
                              marginAbove: "EVEN_MORE",
                              marginBelow: "EVEN_MORE"
                            )
                          },
                          marginAbove: "LESS",
                          showBorder: false,
                          showShadow: false
                        )
                      )
                    }
                  )
                },
                showWhen: count(local!documentAggregate) <> 0,
                padding: "LESS"
              ),
              #"SYSTEM_SYSRULES_cardLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_sectionLayout_v1"(
                    contents: {
                      #"SYSTEM_SYSRULES_cardLayout"(
                        contents: {
                          #"SYSTEM_SYSRULES_sectionLayout_v1"(
                            marginAbove: "EVEN_MORE",
                            marginBelow: "EVEN_MORE"
                          ),
                          if(
                            a!isNullOrEmpty(local!selectedDocument),
                            {},
                            {
                              #"SYSTEM_SYSRULES_sectionLayout_v1"(marginAbove: "MORE"),
                              #"SYSTEM_SYSRULES_richTextDisplayField"(
                                label: "Sin documentos para mostrar",
                                labelPosition: "COLLAPSED",
                                value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                                  text: "Sin documentos para mostrar",
                                  size: "MEDIUM_PLUS"
                                ),
                                marginBelow: "MORE",
                                align: "CENTER"
                              )
                            }
                          ),
                          #"SYSTEM_SYSRULES_sectionLayout_v1"(
                            marginAbove: "EVEN_MORE",
                            marginBelow: "EVEN_MORE"
                          )
                        },
                        marginAbove: "LESS",
                        showShadow: false,
                        showBorder: false
                      )
                    }
                  )
                },
                showWhen: count(local!documentAggregate) = 0,
                padding: "LESS"
              )
            },
            backgroundColor: "TRANSPARENT",
            padding: "LESS",
            showWhen: local!selectedLayout <> "LIST"
          )
        }
      )
    }
  )
)
